CREATE TABLE IF NOT EXISTS `areas_brutas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `qtd` int DEFAULT NULL,
  `municipio` varchar(100) DEFAULT NULL,
  `num_matricula` varchar(50) DEFAULT NULL,
  `ano_aquisicao` int DEFAULT NULL,
  `area_util_m2` decimal(18,3) DEFAULT NULL,
  `reserva_legal_m2` varchar(50) DEFAULT NULL,
  `area_total_m2` decimal(18,3) DEFAULT NULL,
  `valor_imovel` varchar(200) DEFAULT NULL,
  `grupo` varchar(100) DEFAULT NULL,
  `valor_conjunto` decimal(18,4) DEFAULT NULL,
  `descricao_area` text,
  `matricula_parcelamento` varchar(100) DEFAULT NULL,
  `valor_mercado_2021` decimal(18,4) DEFAULT NULL,
  `valor_subsidiado_2021` decimal(18,4) DEFAULT NULL,
  `valor_mercado_2022` decimal(18,4) DEFAULT NULL,
  `valor_subsidiado_2022` decimal(18,4) DEFAULT NULL,
  `valor_mercado_2023` decimal(18,4) DEFAULT NULL,
  `valor_subsidiado_2023` decimal(18,4) DEFAULT NULL,
  `valor_mercado_2024` decimal(18,4) DEFAULT NULL,
  `valor_subsidiado_2024` decimal(18,4) DEFAULT NULL,
  `ocupacao` varchar(200) DEFAULT NULL,
  `tipo_aquisicao` varchar(200) DEFAULT NULL,
  `registro_propriedade` varchar(100) DEFAULT NULL,
  `link_geo` text,
  `link_matricula` text,
  `numero_processo` varchar(200) DEFAULT NULL,
  `tipo` varchar(30) DEFAULT 'imovel',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

